package com.cpf.starter.grpc;import io.grpc.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;public final class CpfGrpcClient implements AutoCloseable {private final ManagedChannel channel;private final CpfGrpcProperties p;private final AtomicInteger pending=new AtomicInteger();public CpfGrpcClient(ManagedChannel c,CpfGrpcProperties p){channel=c;this.p=p;}public byte[] unary(String fullMethod,byte[] request,Metadata metadata){if(pending.incrementAndGet()>p.getMaxPending()){pending.decrementAndGet();throw new RejectedExecutionException("gRPC pending limit");}try{MethodDescriptor<byte[],byte[]> method=MethodDescriptor.<byte[],byte[]>newBuilder().setType(MethodDescriptor.MethodType.UNARY).setFullMethodName(fullMethod).setRequestMarshaller(new Bytes()).setResponseMarshaller(new Bytes()).build();Channel attached=ClientInterceptors.intercept(channel,MetadataUtils.newAttachHeadersInterceptor(metadata==null?new Metadata():metadata));return ClientCalls.blockingUnaryCall(attached,method,CallOptions.DEFAULT.withDeadlineAfter(p.getDeadline().toMillis(),TimeUnit.MILLISECONDS),request);}catch(StatusRuntimeException ex){if(ex.getStatus().getCode()==Status.Code.DEADLINE_EXCEEDED||ex.getStatus().getCode()==Status.Code.UNAVAILABLE)throw new UnknownResultException(ex);throw ex;}finally{pending.decrementAndGet();}}public void close(){channel.shutdown();}private static final class Bytes implements MethodDescriptor.Marshaller<byte[]>{public InputStream stream(byte[] v){return new ByteArrayInputStream(v);}public byte[] parse(InputStream in){try{return in.readAllBytes();}catch(IOException ex){throw new UncheckedIOException(ex);}}}public static final class UnknownResultException extends RuntimeException{UnknownResultException(Throwable c){super("gRPC result unknown; reconcile before retry",c);}}}
